import{_ as e,o,c as a,ag as n}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Self-Assessment: Before and After","description":"","frontmatter":{"source":"assessment/self-assessment.md"},"headers":[],"relativePath":"assessment/self-assessment.md","filePath":"assessment/self-assessment.md"}'),s={name:"assessment/self-assessment.md"};function d(r,t,i,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="self-assessment-before-and-after" tabindex="-1">Self-Assessment: Before and After <a class="header-anchor" href="#self-assessment-before-and-after" aria-label="Permalink to &quot;Self-Assessment: Before and After&quot;">​</a></h1><blockquote><p>A 15-minute survey you take at the start of the course and again at the end. It shows how your confidence and your understanding changed, and whether they match.</p></blockquote><p>🔴 <strong>AI off, and not graded.</strong> Answer on your own, without AI or search. There&#39;s no penalty for wrong answers or low ratings. The only way to get this wrong is to guess what you think we want to hear.</p><h2 id="why-we-do-this" tabindex="-1">Why we do this <a class="header-anchor" href="#why-we-do-this" aria-label="Permalink to &quot;Why we do this&quot;">​</a></h2><p>Two things can grow in a course like this: how confident you feel, and what you can actually do. They don&#39;t always grow together. In one study, students who struggled with AI tools finished believing they had done better than they had (<a href="https://dl.acm.org/doi/10.1145/3632620.3671116" target="_blank" rel="noreferrer">Prather et al.</a>). Experienced developers in another study were 19% slower with AI but believed they were about 20% faster (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR 2025</a>).</p><p>No controlled study yet shows how much programming knowledge people need to vibe-code safely, and there is still no semester-long trial of teaching non-programmers this way. This course&#39;s students have taken one programming course, but most are new to the web, git and AI agents, so the course measures its own students&#39; understanding before and after (<a href="./../research/landscape-report-2026-09.html">September landscape report</a>; <a href="./../research/landscape-update-2026-10.html">October update</a>). Your answers help you see your own progress, and help us improve the course.</p><h2 id="when-and-how" tabindex="-1">When and how <a class="header-anchor" href="#when-and-how" aria-label="Permalink to &quot;When and how&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Pre-course</th><th>Post-course</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>During week 1 (it&#39;s on the week 1 checklist)</td><td>At the Project Fair (week 16, finals week)</td></tr><tr><td><strong>Where</strong></td><td>On <strong>Canvas</strong>, the course&#39;s learning management system, as an ungraded survey</td><td>The same survey on Canvas</td></tr><tr><td><strong>Time</strong></td><td>About 15 minutes</td><td>About 15 minutes</td></tr><tr><td><strong>Graded?</strong></td><td>No. Completion is noted</td><td>No. Completion is noted</td></tr></tbody></table><p>Your answers stay on Canvas, where only you and the course staff can see them. Don&#39;t put them in a repository. Your final capstone reflection asks you to compare your pre-course and post-course answers, so you can look back at them on Canvas.</p><hr><h2 id="part-a-confidence" tabindex="-1">Part A: Confidence <a class="header-anchor" href="#part-a-confidence" aria-label="Permalink to &quot;Part A: Confidence&quot;">​</a></h2><p>For each statement, choose how confident you are <strong>right now</strong>.</p><p><strong>Scale:</strong> <strong>1</strong> I wouldn&#39;t know where to start · <strong>2</strong> Only with a lot of help · <strong>3</strong> With some help · <strong>4</strong> On my own, slowly · <strong>5</strong> On my own, and I could explain it to someone else</p><table tabindex="0"><thead><tr><th>#</th><th>I could…</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr></thead><tbody><tr><td>C1</td><td>explain in plain words what an AI model is doing when it writes code</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C2</td><td>write a prompt that gets an AI to build a small feature I can check</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C3</td><td>write a one-page plan (spec) for an app, with requirements someone else could test</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C4</td><td>publish a web page so that anyone with the link can see it</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C5</td><td>save versions of my work and go back to an earlier one if something breaks</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C6</td><td>read an error message and find the line of code that caused it</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C7</td><td>explain, line by line, a short piece of code that I didn&#39;t write</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C8</td><td>test an app with unusual inputs, not just the normal case</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C9</td><td>keep a secret key safe when building an app that needs one</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C10</td><td>say who can read and change the data in an app I built</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C11</td><td>let an AI agent change my project safely, and check what it did</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr><tr><td>C12</td><td>switch to a different AI tool when my usual one stops working</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td><td>☐</td></tr></tbody></table><h2 id="part-b-concept-checks" tabindex="-1">Part B: Concept checks <a class="header-anchor" href="#part-b-concept-checks" aria-label="Permalink to &quot;Part B: Concept checks&quot;">​</a></h2><p>Answer each question. In the pre-course survey it&#39;s fine to write &quot;I don&#39;t know&quot;; that&#39;s useful information too.</p><p><strong>Q1.</strong> Your app is published on the web. Its code is stored in a <strong>private</strong> repository. The project contains these files:</p><ul><li><code>public/index.html</code> (the page)</li><li><code>public/app.js</code> (the page&#39;s JavaScript)</li><li><code>api/ask.js</code> (code that runs on the server)</li><li><code>.env</code> (settings, including a secret key, on your computer only)</li><li><code>README.md</code> (notes about the project)</li></ul><p><strong>Which of these files can a visitor to your website see or download? Tick all that apply.</strong></p><p>☐ <code>public/index.html</code> ☐ <code>public/app.js</code> ☐ <code>api/ask.js</code> ☐ <code>.env</code> ☐ <code>README.md</code> ☐ I don&#39;t know</p><p><strong>Q2.</strong> Your app uses a paid AI service that needs a secret key. <strong>Where should the key live?</strong></p><ul><li>☐ (a) At the top of <code>app.js</code>, so the page can use it</li><li>☐ (b) In a hidden field in <code>index.html</code></li><li>☐ (c) In an environment variable that only the server code reads</li><li>☐ (d) In a code comment, so you remember it</li><li>☐ I don&#39;t know</li></ul><p><strong>Q3.</strong> <strong>Which of these requirements could someone test by using the app?</strong></p><ul><li>☐ (a) &quot;The app should be fast and easy to use.&quot;</li><li>☐ (b) &quot;WHEN I press Add with an empty box, THE APP SHALL add nothing and SHALL show &#39;Please type something&#39;.&quot;</li><li>☐ (c) &quot;The app handles errors well.&quot;</li><li>☐ (d) &quot;The app should look modern.&quot;</li><li>☐ I don&#39;t know</li></ul><p><strong>Q4.</strong> Your browser shows this error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Uncaught ReferenceError: scroe is not defined</span></span>
<span class="line"><span>    at app.js:22</span></span></code></pre></div><p><strong>Which file and line would you look at, and what&#39;s most likely wrong?</strong> (One or two sentences.)</p><p>Answer: ____________________________________________________________</p><p><strong>Q5.</strong> You saved a change to your project that broke it, and you want to undo that change <strong>while keeping a record of what happened</strong>. <strong>What&#39;s the best option?</strong></p><ul><li>☐ (a) Delete the project and start again</li><li>☐ (b) Use git to &quot;revert&quot; the bad change</li><li>☐ (c) Keep editing files until it works again</li><li>☐ (d) Ask the AI to undo everything it did today</li><li>☐ I don&#39;t know</li></ul><p><strong>Q6.</strong> Your web page talks directly to a database using a key that anyone can see in the browser. <strong>What stops a stranger from reading everyone&#39;s data?</strong></p><ul><li>☐ (a) Nothing needs to: the key is long, so nobody can guess it</li><li>☐ (b) Access rules in the database that decide who can read or change each row</li><li>☐ (c) Hiding the key in a file with a confusing name</li><li>☐ (d) The padlock (HTTPS) in the address bar</li><li>☐ I don&#39;t know</li></ul><h2 id="part-c-two-open-questions" tabindex="-1">Part C: Two open questions <a class="header-anchor" href="#part-c-two-open-questions" aria-label="Permalink to &quot;Part C: Two open questions&quot;">​</a></h2><p><strong>Pre-course:</strong> What do you most want to be able to build or do by the end of this course?</p><p><strong>Post-course:</strong> What can you do now that you couldn&#39;t do in week 1? What do you still want to learn?</p><hr>`,36)])])}const g=e(s,[["render",d]]);export{u as __pageData,g as default};
